import{_ as e,o as t,c as r,ag as i}from"./chunks/framework.DMXcdKmJ.js";const _=JSON.parse('{"title":"管理运行节点","description":"核对节点接入码、安装包、接入申请、运行状态与环境关联，并分清取消分配和移除登记。","frontmatter":{"title":"管理运行节点","description":"核对节点接入码、安装包、接入申请、运行状态与环境关联，并分清取消分配和移除登记。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/runtime-nodes.md","filePath":"zh/使用指南/管理运行节点.md"}'),o={name:"zh/guide/runtime-nodes.md"};function n(l,a,s,d,h,p){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="管理运行节点" tabindex="-1">管理运行节点 <a class="header-anchor" href="#管理运行节点" aria-label="Permalink to &quot;管理运行节点&quot;">​</a></h1><p>不清楚节点、运行环境和基础服务的关系时，先看<a href="/induframe-docs/zh/concepts/environments-and-nodes.html">运行环境与节点说明</a>。</p><p>由组织管理员或运维人员进入 <strong>“运维管理” → “节点管理”</strong>。节点是实际服务器，先取得服务器负责人的授权，再安装、接入或调整归属。</p><p>服务器系统优先使用当前已测试的 Ubuntu 24，其他系统尚未测试；本页不因界面列出其他系统或架构选项就扩大验证范围。</p><p>准备接入新服务器时，先按<a href="/induframe-docs/zh/installation/network.html#_5-多台节点还要确认后台连接">中心与节点怎样互通</a>记录内网地址，分别检查中心和每台节点的规则。只让节点联系到平台，还不代表加入集群、下载运行程序和跨机器通信都已准备好。</p><h2 id="_1-生成接入资料" tabindex="-1">1. 生成接入资料 <a class="header-anchor" href="#_1-生成接入资料" aria-label="Permalink to &quot;1. 生成接入资料&quot;">​</a></h2><ol><li>点击 <strong>“接入节点”</strong>。</li><li>填写可识别的节点名称和接入码有效期。</li><li>点击 <strong>“生成接入码”</strong>。</li><li>核对一次性接入码和节点可访问的中心地址，按页面保存。</li></ol><p>接入码是敏感资料，不放进公开手册、截图、工单正文或源码。过期、已使用或无法查看时，先核对记录，再按需要重新生成，不重复分享旧码。</p><h2 id="_2-在目标服务器安装" tabindex="-1">2. 在目标服务器安装 <a class="header-anchor" href="#_2-在目标服务器安装" aria-label="Permalink to &quot;2. 在目标服务器安装&quot;">​</a></h2><p>从平台的 **“下载节点安装包”**选择与目标系统、CPU 架构一致的交付包。按页面及随包说明在目标服务器运行安装程序，粘贴本次接入码。</p><p>需要手动安装时，使用当前页面实际给出的连接地址和安装说明，不从其他环境抄一条命令。中心地址必须能被目标节点访问，不能把浏览器电脑上的 localhost 当成中心地址。</p><p>安装包完成不代表工程镜像、正式采集运行时或工程部署都已经准备好。</p><h2 id="_3-核对接入申请与状态" tabindex="-1">3. 核对接入申请与状态 <a class="header-anchor" href="#_3-核对接入申请与状态" aria-label="Permalink to &quot;3. 核对接入申请与状态&quot;">​</a></h2><p>出现接入申请时，核对主机名称、地址和来源。确认是获准服务器后再点击“确认”，按对话框执行 <strong>“确认接入”</strong>；无法确认身份时先拒绝或联系负责人。</p><p>接入后检查：</p><ul><li>连接状态与最近心跳。</li><li>节点类型、Agent 版本和实际地址。</li><li>CPU、内存、磁盘等资源使用。</li><li>时间同步和运行底座、运行资格相关提示。</li></ul><p>在线只表示连接层面的状态，不保证驱动能力、运行资格、容量和设备网络全部合格。</p><h2 id="_4-关联运行环境或采集连接" tabindex="-1">4. 关联运行环境或采集连接 <a class="header-anchor" href="#_4-关联运行环境或采集连接" aria-label="Permalink to &quot;4. 关联运行环境或采集连接&quot;">​</a></h2><p>通过<a href="/induframe-docs/zh/guide/runtime-environments.html">运行环境</a>将节点关联到合适范围。工程部署和工业采集按各自条件选择节点，不能把节点加入环境等同于所有采集连接都已分配。</p><p>工业连接的落点和验证见<a href="/induframe-docs/zh/guide/industrial-connections.html">工业采集说明</a>。界面没有兼容节点时，先核对节点状态和能力，不更换协议绕过检查。</p><h2 id="_5-取消分配与移除登记不同" tabindex="-1">5. 取消分配与移除登记不同 <a class="header-anchor" href="#_5-取消分配与移除登记不同" aria-label="Permalink to &quot;5. 取消分配与移除登记不同&quot;">​</a></h2><ul><li><strong>取消分配</strong>：从某个运行环境移除关联，节点仍保留在中心登记中。</li><li><strong>移除运行节点</strong>：撤销中心登记与接入凭据，需要先满足环境和部署的清理条件。</li><li><strong>卸载节点本机程序</strong>：是另一项操作；移除登记不会远程自动删除本机程序和数据。</li></ul><p>承载基础服务、工程或中心控制面的节点可能禁止取消分配或移除。先查明依赖、通知业务负责人，不绕过保护，也不直接删除服务器目录。</p><p>操作后到列表和<a href="/induframe-docs/zh/guide/operations-records.html">运维记录</a>确认结果，状态不明时先刷新，不连续提交移除。</p>',24)])])}const c=e(o,[["render",n]]);export{_ as __pageData,c as default};
